<?php defined('BASEPATH') OR exit('No direct script access allowed');
class Checkout extends MY_Controller { public function __construct(){parent::__construct();$this->load->model('Order_model');$this->load->model('User_model');}
 public function index(){ $this->require_login();$cart=$this->session->userdata('cart')?:array();if(!$cart){redirect('cart');}$this->view('checkout/index',array('cart'=>$cart,'user'=>$this->User_model->find($this->session->userdata('user_id')))); }
 public function place_order(){ $this->require_login();$cart=$this->session->userdata('cart')?:array();if(!$cart)redirect('cart');$this->form_validation->set_rules('payment_method','Payment method','required|in_list[cod,card,banking,paytm]');$this->form_validation->set_rules('shipping_address','Shipping address','required|trim');if(!$this->form_validation->run()){$this->view('checkout/index',array('cart'=>$cart,'user'=>$this->User_model->find($this->session->userdata('user_id'))));return;} $oid=$this->Order_model->create($this->session->userdata('user_id'),$cart,$this->input->post('payment_method',true),$this->input->post('shipping_address',true));if(!$oid)show_error('Unable to place order.');$this->session->unset_userdata('cart');redirect('order/confirmation/'.$oid);}
}
